<script setup lang="ts">
import { ref } from 'vue';
import { useSession } from '../stores/session';
import BusinessShell from './BusinessShell.vue';
import { usePolling, errorText, stateName, type Task, type Rider, type Asset } from './model';
const session=useSession(),enterprise=ref<{enterprise_name:string;boxes:Asset[]}|null>(null),tasks=ref<Task[]>([]),riders=ref<Rider[]>([]),selected=ref<Record<string,string>>({}),busy=ref(false),actionError=ref('');
const {error,loading,refresh}=usePolling(async signal=>{const result=await Promise.all([session.request<{enterprise_name:string;boxes:Asset[]}>('/enterprise/boxes',{signal}),session.request<Task[]>('/enterprise/transports',{signal}),session.request<Rider[]>('/enterprise/riders',{signal})]);if(!signal.aborted){enterprise.value=result[0];tasks.value=result[1];riders.value=result[2]; }},()=>{enterprise.value=null;tasks.value=[];riders.value=[];});
async function change(box:string,unassign=false){if(busy.value)return;actionError.value='';busy.value=true;try{await session.request(`/enterprise/boxes/${encodeURIComponent(box)}/${unassign?'unassign':'assign'}`,{method:'POST',body:unassign?undefined:{rider_user_id:BigInt(selected.value[box])}});refresh();}catch(e){actionError.value=errorText(e);}finally{busy.value=false;}}
</script>
<template><BusinessShell><div class="page-heading"><div><p class="biz-muted">企业运营</p><h1>{{ enterprise?.enterprise_name ?? '企业资产' }}</h1><p>分配箱体，跟进每一次运输。</p></div><button class="biz-secondary" @click="refresh">刷新</button></div><p v-if="error||actionError" class="biz-error" role="alert">{{ error||actionError }}</p><p v-if="loading">正在读取企业资产…</p>
 <section class="asset-section"><div class="section-head"><h2>企业箱体</h2><span>{{ enterprise?.boxes.length ?? 0 }} 台</span></div><p v-if="enterprise&&!enterprise.boxes.length">当前企业没有箱体。</p><article class="asset-row" v-for="box in enterprise?.boxes" :key="box.box_id"><div><strong>{{ box.display_name }}</strong><small>{{ box.box_id }}</small></div><span>{{ box.rider_username ? `使用骑手：${box.rider_username}`:'尚未分配' }}</span><button v-if="box.rider_user_id" class="biz-secondary" :disabled="busy" @click="change(box.box_id,true)">收回分配</button><form v-else @submit.prevent="change(box.box_id)"><label :for="`rider-${box.box_id}`" class="sr-only">选择骑手 {{ box.box_id }}</label><select :id="`rider-${box.box_id}`" v-model="selected[box.box_id]" required><option disabled value="">选择演示骑手</option><option v-for="rider in riders" :key="String(rider.user_id)" :value="String(rider.user_id)">{{ rider.username }}</option></select><button class="biz-primary" :disabled="busy||!selected[box.box_id]">分配箱体</button></form></article></section>
 <section class="task-section"><h2>最近运输</h2><p v-if="!tasks.length" class="biz-muted">尚无运输任务，分配箱体后由骑手创建。</p><RouterLink class="task-row" v-for="task in tasks" :key="String(task.task_id)" :to="`/enterprise/transports/${task.task_id}`"><div><strong>{{ task.item_name || '未填写物品' }}</strong><small>{{ task.transport_no }} · {{ task.box_id }}</small></div><span :class="['task-state',task.status]">{{ stateName(task.status) }}</span><span>查看任务 ›</span></RouterLink></section>
 </BusinessShell></template>
